-- ----------------------------
-- Table structure for project_members
-- ----------------------------
DROP TABLE IF EXISTS `project_members`;
CREATE TABLE `project_members` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '成员ID',
  `project_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目ID（逻辑关联）',
  `user_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户ID（逻辑关联）',
  `role` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目角色（详见字典表decoration_job_roles）',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否启用（0:已移除，1:在职）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人（添加成员的人）',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人（移除/修改的人）',
  `role_category` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '角色分类（MANAGEMENT:管理岗、DESIGN:设计岗、ENGINEERING:工程岗、CONSTRUCTION:施工岗、BUSINESS:商务岗、SUPPORT:支持岗）',
  `skill_level` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '技能等级（JUNIOR:初级、MID:中级、SENIOR:高级、EXPERT:专家）',
  `join_date` datetime DEFAULT NULL COMMENT '加入项目时间',
  PRIMARY KEY (`id`),
  KEY `idx_project_id` (`project_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_role` (`role`),
  KEY `idx_is_active` (`is_active`),
  KEY `idx_role_category` (`role_category`),
  KEY `idx_skill_level` (`skill_level`),
  KEY `idx_join_date` (`join_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目成员表';

-- ----------------------------
-- Records of project_members
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for project_role_templates
-- ----------------------------
DROP TABLE IF EXISTS `project_role_templates`;
CREATE TABLE `project_role_templates` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板ID',
  `template_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板名称',
  `project_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '适用项目类型（RESIDENTIAL:家装、COMMERCIAL:工装）',
  `budget_range` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预算范围（SMALL:<30万、MEDIUM:30-80万、LARGE:80-150万、XLARGE:>150万）',
  `area_range` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '面积范围（SMALL:<80㎡、MEDIUM:80-150㎡、LARGE:150-300㎡、XLARGE:>300㎡）',
  `required_roles` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '必需角色JSON数组',
  `optional_roles` text COLLATE utf8mb4_unicode_ci COMMENT '可选角色JSON数组',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '模板描述',
  `is_default` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否默认模板',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否启用',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`),
  KEY `idx_project_type` (`project_type`),
  KEY `idx_budget_range` (`budget_range`),
  KEY `idx_is_default` (`is_default`),
  KEY `idx_is_active` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目角色配置模板表';

