-- ----------------------------
-- Table structure for project_schedule_records
-- ----------------------------
DROP TABLE IF EXISTS `project_schedule_records`;
CREATE TABLE `project_schedule_records` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键ID（格式：REC + 年月日 + 6位序列号）',
  `project_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目ID（关联projects表）',
  `schedule_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '进度ID（关联project_schedules表）',
  `record_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PROGRESS' COMMENT '记录类型（START:开始、PROGRESS:进度更新、COMPLETE:完成、ISSUE:问题、ACCEPTANCE:验收）',
  `images` json DEFAULT NULL COMMENT '现场图片JSON数组格式（如：["img1.jpg","img2.jpg"]）',
  `acceptance_title` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '验收标题',
  `acceptance_content` text COLLATE utf8mb4_unicode_ci COMMENT '验收内容',
  `acceptance_result` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '验收结果（QUALIFIED:合格、UNQUALIFIED:不合格）',
  `acceptance_time` datetime DEFAULT NULL COMMENT '验收时间（实际验收发生时间）',
  `acceptor` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '验收人（实际验收人员姓名）',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间（系统自动）',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '记录更新时间（系统自动）',
  `created_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '记录创建人（系统自动，存储用户ID）',
  `updated_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '记录更新人（系统自动，存储用户ID）',
  PRIMARY KEY (`id`),
  KEY `idx_project` (`project_id`),
  KEY `idx_schedule` (`schedule_id`),
  KEY `idx_record_type` (`record_type`),
  KEY `idx_acceptance_title` (`acceptance_title`),
  KEY `idx_acceptance_time` (`acceptance_time`),
  KEY `idx_acceptor` (`acceptor`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目进度记录表（包含验收功能）';

-- ----------------------------
-- Records of project_schedule_records
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for project_schedules
-- ----------------------------
DROP TABLE IF EXISTS `project_schedules`;
CREATE TABLE `project_schedules` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '进度ID',
  `project_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目ID',
  `stage` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '施工阶段（DISMANTLING:拆除、WATER_ELECTRIC:水电、TILES:泥瓦、WOODWORK:木工、PAINTING:油漆、INSTALLATION:安装、SOFT_FURNISHING:软装、ACCEPTANCE:验收）',
  `stage_order` int NOT NULL COMMENT '阶段顺序（1-8）',
  `plan_start_date` datetime DEFAULT NULL COMMENT '计划开始日期',
  `plan_end_date` datetime DEFAULT NULL COMMENT '计划结束日期',
  `actual_start_date` datetime DEFAULT NULL COMMENT '实际开始日期',
  `actual_end_date` datetime DEFAULT NULL COMMENT '实际结束日期',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT '阶段状态',
  `completion_rate` decimal(5,2) DEFAULT '0.00' COMMENT '完成度百分比',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '阶段描述',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`),
  KEY `idx_project_id` (`project_id`),
  KEY `idx_stage` (`stage`),
  KEY `idx_status` (`status`),
  KEY `idx_stage_order` (`stage_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目进度表';

-- ----------------------------
-- Records of project_schedules
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for projects
-- ----------------------------
DROP TABLE IF EXISTS `projects`;
CREATE TABLE `projects` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目ID',
  `project_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'RESIDENTIAL' COMMENT '项目类型（RESIDENTIAL:家装、COMMERCIAL:工装）',
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目名称',
  `customer_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户ID',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '项目描述',
  `address` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目地址',
  `area` decimal(10,2) DEFAULT NULL COMMENT '房屋面积（平米）',
  `budget` decimal(15,2) DEFAULT NULL COMMENT '预算金额',
  `actual_cost` decimal(15,2) DEFAULT '0.00' COMMENT '实际费用',
  `start_date` datetime DEFAULT NULL COMMENT '开始日期',
  `end_date` datetime DEFAULT NULL COMMENT '预计完工日期',
  `actual_end_date` datetime DEFAULT NULL COMMENT '实际完工日期',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PLANNING' COMMENT '项目状态',
  `priority` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MEDIUM' COMMENT '优先级',
  `progress` decimal(5,2) DEFAULT '0.00' COMMENT '进度百分比',
  `budgets_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预算文件URL',
  `contracts_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '合同文件URL',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`),
  KEY `idx_project_type` (`project_type`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_status` (`status`),
  KEY `idx_priority` (`priority`),
  KEY `idx_active_deleted` (`deleted_at`),
  KEY `idx_name` (`name`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目信息表';

-- ----------------------------
-- Records of projects
-- ----------------------------
BEGIN;
COMMIT;

